import re
import logging


class DspParser(object):
    def __init__(self, input_log):
        """
        :param  input_log: log file to parse
        """
        self.dsp_file = input_log
        self.data = {
            "timestamp": []
        }
        self.dsps_names = []

    def get_data(self):
        return self.data

    def parse(self):
        """
        Start parsing file.
        """
        try:
            with open(self.dsp_file) as input_file:
                for line in input_file:
                    self.analyze(line, input_file)
        except IOError:
            logging.debug("DSP_Parser: Unable to open file {} or file doesn't exist".format(str(self.dsp_file)))

    def analyze(self, line, input_file):
        """
        Parse one data line.
        """
        if "Get CPU Loads for all DSPs on KEPLER..." in line:
            for line in input_file:
                if "update every 10 s. Press ^C to exit" in line:
                    self._analyze_timestamp(line)
                    return 0
                else:
                    self._analyze_dsp_load(line)

    # 2020.05.22 14:43:29
    _re_timestamp = re.compile(r"(?P<TIMESTAMP>\d{4}.\d{2}.\d{2} \d{2}:\d{2}:\d{2})")

    def _analyze_timestamp(self, line):
        """
        Parse datetime and add to timestamp list.
        """
        if "update every 10 s. Press ^C to exit" in line:
            line = DspParser._re_timestamp.search(line).group('TIMESTAMP')
            self.data["timestamp"].append(line)

    # 1 2 1
    _re_dsps_integers = re.compile(r"(?P<INTEGERS>\d \d \d)")

    # 26.96
    _re_float = re.compile(r"(?P<FLOAT>\d+\.\d+)")

    # FSP
    _re_uppercase_text = re.compile(r"(?P<TEXT>[A-Z])\w+")

    def _analyze_dsp_load(self, line):
        """
        Parse given line and add to data dictionary in a good place.
        """
        if '%' in line:
            dsps_numbers = DspParser._re_dsps_integers.search(line).group('INTEGERS').split()
            dsps = [name + number for name, number in zip(self.dsps_names, dsps_numbers)]

            load = DspParser._re_float.search(line).group('FLOAT')

            if self._check_if_key_exists(dsps[0], self.data):
                if self._check_if_key_exists(dsps[1], self.data[dsps[0]]):
                    self._append_core_load(load, dsps)
                else:
                    self.data[dsps[0]][dsps[1]] = {}
                    self._append_core_load(load, dsps)
            else:
                self.data[dsps[0]] = {}
                self.data[dsps[0]][dsps[1]] = {}
                self._append_core_load(load, dsps)
        else:
            name = DspParser._re_uppercase_text.search(line)
            if name is not None:
                dsp_name = name.group(0)
                if dsp_name not in self.dsps_names:
                    self.dsps_names.append(dsp_name)

    def _append_core_load(self, load, dsps):
        """
        Append given load value to list in data dictionary.
        """
        if self._check_if_key_exists(dsps[2], self.data[dsps[0]][dsps[1]]):
            self.data[dsps[0]][dsps[1]][dsps[2]].append(float(load))
        else:
            self.data[dsps[0]][dsps[1]][dsps[2]] = []
            self.data[dsps[0]][dsps[1]][dsps[2]].append(float(load))

    @staticmethod
    def _check_if_key_exists(key, dictionary):
        if key in dictionary.keys():
            return True
        else:
            return False


